def job(j, lang):
    company, role, dates, en, es, stack = j
    return f'<article class="job"><div class="job-meta"><span>{escape(dates.format(present=DATA[lang]["present"]))}</span><h3>{escape(company)}</h3><p>{escape(role)}</p></div><div><p>{escape(es if lang=="es" else en)}</p><p class="stack">{escape(stack)}</p></div></article>'
def build(lang, resume=False):
    d=DATA[lang]; home='/' if lang=='en' else '/landing_es/'; cv='/cv/' if lang=='en' else '/landing_es/cv/'; other=('/landing_es/cv/' if lang=='en' else '/cv/') if resume else ('/landing_es/' if lang=='en' else '/')
    path=cv if resume else home
    pdf=f'/files/cv/Francisco-Caro-Diaz-CV-{lang.upper()}.pdf'
    download='Descargar CV en PDF' if lang=='es' else 'Download résumé PDF'
    title='Francisco Caro Díaz | '+('Currículum · Mobile Engineer' if lang=='es' and resume else 'Résumé · Mobile Engineer' if resume else 'Senior Android & iOS Engineer · Mobile Tech Lead')
    desc=d['intro']
    nav=''.join(f'<a href="{home}#{a}">{label}</a>' for a,label in zip(['work','approach','writing','contact'],d['nav']))
    intro = f'<section class="hero"><div><p class="eyebrow">{d["eyebrow"]}</p><h1>{d["hero"]}</h1><p class="intro">{d["intro"]}</p><div class="actions"><a class="button" href="{cv}">{d["cv"]} <span aria-hidden="true">↗</span></a><a class="text-link" href="{pdf}" download>{download} ↓</a><a class="text-link" href="{LINKEDIN}">LinkedIn ↗</a></div><p class="experience-note">{d["years"]}</p></div><aside class="platform" aria-label="Android and iOS expertise"><div class="platform-top"><span>FC / MOBILE</span><span class="dot" aria-hidden="true"></span></div><div class="platform-name">Android<span>+</span>iOS</div><div class="platform-code"><span>Kotlin / Compose</span><span>Swift / SwiftUI</span></div><div class="platform-base">Architecture → Quality → Delivery</div><p>Hands-on engineering<br>End-to-end ownership</p></aside></section>'
    if resume:
        intro=f'<section class="resume-head"><p class="eyebrow">{d["full"]}</p><h1>Francisco<br>Caro Díaz<span class="accent">.</span></h1><p class="intro">Senior Android & iOS Engineer · Mobile Tech Lead</p><p>{d["intro"]}</p><div class="actions"><a class="button" href="{pdf}" download>{download} ↓</a><button class="button print-button" onclick="window.print()">{d["print"]}</button><a href="{home}" class="text-link">{d["back"]} ↗</a></div></section>'
    work=f'<section id="work"><div class="section-head"><p class="eyebrow">01 / {d["nav"][0]}</p><h2>{d["work"]}</h2><p>{d["workintro"]}</p></div>'+''.join(job(j,lang) for j in (JOBS if resume else JOBS[:3]))
    if not resume: work+=f'<a class="text-link section-link" href="{cv}">{d["full"]} →</a>'
    work+='</section>'
    pillars=''.join(f'<article><span class="number">0{i+1}</span><h3>{t}</h3><p>{b}</p></article>' for i,(t,b) in enumerate(d['pillars']))
    approach=f'<section id="approach"><div class="section-head"><p class="eyebrow">02 / {d["nav"][1]}</p><h2>{d["approach"]}</h2><p>{d["approachintro"]}</p></div><div class="grid three">{pillars}</div><div class="expertise"><h3>{d["skills"]}</h3><p>Kotlin · Jetpack Compose · Swift · SwiftUI · Clean Architecture · MVVM · CI/CD · Testing · Firebase · REST · GraphQL</p></div></section>'
    writing=f'<section id="writing"><div class="section-head"><p class="eyebrow">03 / {d["nav"][2]}</p><h2>{d["writing"]}</h2><p>{d["writingintro"]}</p></div><div class="grid two">'+''.join(f'<a class="article-card" href="{url}"><span class="eyebrow">{date} · LinkedIn</span><h3>{d["articletexts"][i]} <span aria-hidden="true">↗</span></h3><p>{d["articlebody"][i]}</p></a>' for i,(url,date) in enumerate(zip(ARTICLES,['01.11.2024','05.06.2024'])))+'</div></section>'
    projects=f'<section class="projects"><div class="section-head"><h2>{d["projects"]}</h2><p>{d["projectintro"]}</p></div><div class="grid two"><article><p class="eyebrow">2015 · WatchKit</p><h3><a href="https://github.com/franciscocarodiaz/BitWatch-App">BitWatch ↗</a></h3><p>'+('An early Apple Watch experiment with real-time Bitcoin data and shared app data.' if lang=='en' else 'Un experimento temprano para Apple Watch con datos de Bitcoin en tiempo real y datos compartidos entre apps.')+'</p></article><article><p class="eyebrow">2014 · Redbooth WatchKit Hackathon</p><h3><a href="https://dribbble.com/shots/1846017-Redkitt-Redbooth-Hackaton">RedKitt ↗</a></h3><p>'+('Awarded “The best use of the Redbooth API” at the Barcelona hackathon.' if lang=='en' else 'Premio «The best use of the Redbooth API» en el hackathon de Barcelona.')+'</p></article></div></section>'
    education=f'<section><div class="section-head"><h2>{d["education"]}</h2></div><ul class="education"><li><strong>Universidad de Sevilla</strong><span>Computer Science / Ingeniería Informática · 2003–2011</span></li><li><strong>Universidad de Sevilla</strong><span>Master: Web & Mobile Development · 2011–2012<br>Master: E-learning · 2010–2012</span></li><li><strong>Ironhack · Barcelona</strong><span>iOS Development Bootcamp · 2014 · 400+ hours</span></li><li><strong>Udacity / Stanford</strong><span>Android / iOS with Swift · 2015</span></li><li><strong><a href="https://scrummanager.com/index.php/en/public-profile?id=19504">Scrum Manager ↗</a></strong><span>Scrum Expert · ID 19504</span></li></ul></section>' if resume else ''
    contact=f'<section id="contact" class="contact"><p class="eyebrow">{d["location"]}</p><h2>{d["contact"]}</h2><p>{d["contactbody"]}</p><a class="button" href="mailto:franciscocarodiaz@gmail.com">{d["email"]} <span aria-hidden="true">↗</span></a><div class="contact-links"><a href="{LINKEDIN}">LinkedIn ↗</a><a href="{GITHUB}">GitHub ↗</a><a href="mailto:franciscocarodiaz@gmail.com">franciscocarodiaz@gmail.com</a></div></section>'
    page = f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="theme-color" content="#f4f3ee"><link rel="canonical" href="{BASE}{path}"><link rel="alternate" hreflang="en" href="{BASE}{'/cv/' if resume else '/'}"><link rel="alternate" hreflang="es" href="{BASE}{'/landing_es/cv/' if resume else '/landing_es/'}"><link rel="alternate" hreflang="x-default" href="{BASE}{'/cv/' if resume else '/'}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="{BASE}{path}"><meta property="og:image" content="{BASE}/assets/social-card.png"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/site.css"></head><body><a class="skip" href="#main">{'Saltar al contenido' if lang=='es' else 'Skip to content'}</a><header><a class="brand" href="{home}" aria-label="Francisco Caro Díaz"><span class="monogram">fc.</span><span>Francisco Caro Díaz</span></a><nav aria-label="{'Navegación principal' if lang=='es' else 'Main navigation'}">{nav}<a class="language" href="{other}" lang="{'es' if lang=='en' else 'en'}">{'ES' if lang=='en' else 'EN'}</a></nav></header><main id="main">{intro}{work}{approach}{education}{'' if resume else writing+projects}{contact}</main><footer><span>© {2026} Francisco Caro Díaz</span><span>{d['foot']}</span></footer></body></html>'''
    if lang == 'es':
        translations = {'Aug 2020':'Ago 2020','Jan 2015':'Ene 2015','Apr 2013':'Abr 2013','Sep 2008':'Sep 2008','Architecture → Quality → Delivery':'Arquitectura → Calidad → Entrega','Hands-on engineering':'Desarrollo directo','End-to-end ownership':'Responsabilidad integral','Architecture · Mentoring':'Arquitectura · Mentoring','Mobile development':'Desarrollo mobile','Computer Science / Ingeniería Informática':'Ingeniería Informática','Master: Web & Mobile Development':'Máster: Desarrollo Web y Mobile','Master: E-learning':'Máster: E-learning','iOS Development Bootcamp':'Bootcamp de Desarrollo iOS','400+ hours':'Más de 400 horas','Android / iOS with Swift':'Android / iOS con Swift'}
        for original, translated in translations.items(): page = page.replace(original, translated)
    return page
for lang, paths in [('en',['index.html','home/landing.html']),('es',['landing_es/index.html','landing_es/home/landing.html'])]:
    for path in paths: (ROOT/path).write_text(build(lang), encoding='utf-8')
for lang,path in [('en','cv/index.html'),('es','landing_es/cv/index.html')]: (ROOT/path).write_text(build(lang,True),encoding='utf-8')
